bool isIn(vec2 z){return length(z)<10.0;}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //variables
    float ITERATIONS = 300.0;
    float ZOOM;
    float time = (19.25)/5.0;
    vec2 C=0.65*vec2(sin(iTime*2.),cos(iTime/2.5));
    vec2 P=0.65*vec2(sin(iTime),cos(iTime/3.));
    vec2 COORDS = vec2(0.0,0.0);

    //C=vec2(0.56667,0);
    //P=vec2(-0.5,0);

    if (iMouse.z>0.0){
    ZOOM =10.0;
    COORDS=2.*((2.0*iMouse.xy)-(iResolution.xy))/iResolution.x;
   }else{
    ZOOM =1.0;
    COORDS = vec2(0.0,0.0);
   }
    COORDS=COORDS-(COORDS/ZOOM);

    //get coordinate
    vec2 uv = COORDS+((4.0/ZOOM)*(fragCoord/iResolution.x))-(vec2(2.0,1.125)/ZOOM);

    //iterate equation a bunch
    vec2 z = uv.yx;
    vec2 pastZ=vec2(0);
    float i=0.0;
    for (i=0.0;i<ITERATIONS && isIn(z);++i){
    vec2 temp=vec2((z.x*z.x)-(z.y*z.y),2.0*z.x*z.y)+C+vec2((P.x*pastZ.x)-(P.y*pastZ.y),(P.x*pastZ.y)+(P.y*pastZ.x));
    pastZ=z;
    z=temp;
    }

    //calculate and output color
    vec3 col = vec3(0.0);
    if (!isIn(z)){
    i=i-log2(log(length(z)));
    i=i/5.0;
    col = abs(vec3(sin(i),sin(i+(time)),sin(i+(time/2.0))));
    }
    fragColor = vec4(col,1.0);
}
